import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    public static void main(String[] args) {
        Locker lockerA = new Locker(new ParcelCount(10));
        Locker lockerB = new Locker(new ParcelCount(10));
        Thread t1 = new Thread(() -> {
            try {
                boolean result = transfer(lockerA, lockerB, 2, 10, TimeUnit.SECONDS);
                System.out.println("Transfer 1 result: " + result);
            } catch (NotEnoughItemsException e) {
                System.out.println("Not enough items");
            }
        });
        Thread t2 = new Thread(() -> {
            try {
                boolean result = transfer(lockerB, lockerA, 3, 10, TimeUnit.SECONDS);
                System.out.println("Transfer 2 result: " + result);
            } catch (NotEnoughItemsException e) {
                System.out.println("Not enough items");
            }
        });
        t1.start();
        t2.start();
        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    static class ParcelCount {
        private int count;
        public ParcelCount(int count) { this.count = count; }
        public int getCount() { return count; }
        public void setCount(int count) { this.count = count; }
    }

    static class Locker {
        private final ReentrantLock lock = new ReentrantLock();
        private final ParcelCount parcels;
        public Locker(ParcelCount parcels) { this.parcels = parcels; }
        public ReentrantLock getLock() { return lock; }
        public ParcelCount getParcels() { return parcels; }
    }

    static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String msg) { super(msg); }
    }

    private static final Random random = new Random();

    private static long fixedDelay() { return 50; }
    private static long randomDelay() { return random.nextInt(100); }

    public static boolean transfer(Locker source, Locker target, int quantity, long timeout, TimeUnit unit) throws NotEnoughItemsException {
        long deadline = System.nanoTime() + unit.toNanos(timeout);
        while (true) {
            boolean gotSource = false;
            boolean gotTarget = false;
            try {
                gotSource = source.getLock().tryLock(100, TimeUnit.MILLISECONDS);
                gotTarget = target.getLock().tryLock(100, TimeUnit.MILLISECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            }
            if (gotSource && gotTarget) {
                try {
                    if (source.getParcels().getCount() < quantity) {
                        throw new NotEnoughItemsException("Not enough parcels");
                    }
                    source.getParcels().setCount(source.getParcels().getCount() - quantity);
                    target.getParcels().setCount(target.getParcels().getCount() + quantity);
                    return true;
                } finally {
                    source.getLock().unlock();
                    target.getLock().unlock();
                }
            }
            if (gotSource) source.getLock().unlock();
            if (gotTarget) target.getLock().unlock();
            if (System.nanoTime() > deadline) return false;
            try {
                Thread.sleep(fixedDelay() + randomDelay());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            }
        }
    }
}

