class PublishingVehicleTracker {
    private final ConcurrentHashMap<String, SafePoint> locations = new ConcurrentHashMap<>();

    public void initialize(String id, int x, int y) {
        locations.put(id, new SafePoint(x, y));
    }

    public Map<String, SafePoint> getLocations() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public SafePoint getVehicle(String id) {
        return locations.get(id);
    }

    public void updateVehicle(String id, int x, int y) {
        SafePoint point = locations.get(id);
        if (point == null) {
            throw new IllegalArgumentException("No such vehicle: " + id);
        }
        point.set(x, y);
    }
}

