import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.CopyOnWriteArrayList;

public class Main {
    public static void main(String[] args) throws Exception {
        List<Talisman> talismans = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            talismans.add(new Talisman() {});
        }
        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<String> results = processParallel(talismans, executor);
        System.out.println("Parallel results: " + results);
        executor.shutdown();
    }

    interface Talisman {
    }

    interface SigilNode {
        String compute();
        List<SigilNode> getChildren();
    }

    static String enchant(Talisman t) {
        return "enchanted";
    }

    static List<String> processSequential(List<Talisman> talismans) {
        List<String> results = new ArrayList<>();
        for (Talisman t : talismans) {
            results.add(enchant(t));
        }
        return results;
    }

    static List<String> processParallel(List<Talisman> talismans, ExecutorService executor) throws Exception {
        List<Future<String>> futures = new ArrayList<>();
        for (Talisman t : talismans) {
            futures.add(executor.submit(new Callable<String>() {
                public String call() {
                    return enchant(t);
                }
            }));
        }
        List<String> results = new ArrayList<>();
        for (Future<String> f : futures) {
            results.add(f.get());
        }
        return results;
    }

    static List<String> processSequentialRecursive(SigilNode node) {
        List<String> results = new ArrayList<>();
        results.add(node.compute());
        for (SigilNode child : node.getChildren()) {
            results.addAll(processSequentialRecursive(child));
        }
        return results;
    }

    static List<String> processParallelRecursive(SigilNode node, ExecutorService executor) throws Exception {
        List<Future<List<String>>> futures = new ArrayList<>();
        List<String> results = new CopyOnWriteArrayList<>();
        results.add(node.compute());
        for (SigilNode child : node.getChildren()) {
            futures.add(executor.submit(new Callable<List<String>>() {
                public List<String> call() throws Exception {
                    return processParallelRecursive(child, executor);
                }
            }));
        }
        for (Future<List<String>> f : futures) {
            results.addAll(f.get());
        }
        return results;
    }
}

