}

class OrbVault {
    private final Orb[] items;
    private int putPtr;
    private int takePtr;
    private final Semaphore availableOrbs;
    private final Semaphore availableSlots;

    public OrbVault(int capacity) {
        items = new Orb[capacity];
        availableOrbs = new Semaphore(0);
        availableSlots = new Semaphore(capacity);
    }

    public void put(Orb x) throws InterruptedException {
        availableSlots.acquire();
        synchronized (this) {
            items[putPtr] = x;
            putPtr = (putPtr + 1) % items.length;
        }
        availableOrbs.release();
    }

    public Orb take() throws InterruptedException {
        availableOrbs.acquire();
        Orb item;
        synchronized (this) {
            item = items[takePtr];
            items[takePtr] = null;
            takePtr = (takePtr + 1) % items.length;
        }
        availableSlots.release();
        return item;
    }

    public boolean isEmpty() {
        return availableOrbs.availablePermits() == 0;
    }

    public boolean isFull() {
        return availableSlots.availablePermits() == 0;
    }
}

