        Thread t1 = new Thread(() -> {
            boolean result = counter.compareAndSet(0, 5);
            System.out.println("CAS result: " + result);
        });
        t1.start();
        try {
            t1.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        System.out.println("Final essence: " + counter.get());
