class Constellation<K, V> extends HashMap<K, V> {
}

class ChronomanticDragonTracker {
    private final Map<String, MutableOrb> locations;

    public ChronomanticDragonTracker(Constellation<String, MutableOrb> initial) {
        this.locations = deepClone(initial);
    }

    public synchronized Map<String, MutableOrb> getConstellations() {
        return Collections.unmodifiableMap(deepClone(locations));
    }

    public synchronized MutableOrb getOrb(String sigil) {
        MutableOrb orb = locations.get(sigil);
        return orb == null ? null : new MutableOrb(orb.getX(), orb.getY());
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        MutableOrb orb = locations.get(sigil);
        if (orb == null) {
            throw new IllegalArgumentException("No such dragon: " + sigil);
        }
        orb.set(shimmerX, shimmerY);
    }

    private static Map<String, MutableOrb> deepClone(Map<String, MutableOrb> m) {
        Map<String, MutableOrb> result = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : m.entrySet()) {
            result.put(entry.getKey(), new MutableOrb(entry.getValue().getX(), entry.getValue().getY()));
        }
        return result;
    }
}

