class MutableGem {
    private int glowX;
    private int glowY;

    public MutableGem(int x, int y) {
        this.glowX = x;
        this.glowY = y;
    }

    public int getX() { return glowX; }
    public int getY() { return glowY; }
    public void set(int x, int y) {
        this.glowX = x;
        this.glowY = y;
    }
}

class StarlightMap<K, V> extends HashMap<K, V> {
}

class CelestialGriffinTracker {
    private final Map<String, MutableGem> locations;

    public CelestialGriffinTracker(StarlightMap<String, MutableGem> initial) {
        this.locations = deepForge(initial);
    }

    public synchronized Map<String, MutableGem> getStarlights() {
        return Collections.unmodifiableMap(deepForge(locations));
    }

    public synchronized MutableGem getGem(String rune) {
        MutableGem gem = locations.get(rune);
        return gem == null ? null : new MutableGem(gem.getX(), gem.getY());
    }

    public synchronized void setGem(String rune, int glowX, int glowY) {
        MutableGem gem = locations.get(rune);
        if (gem == null) {
            throw new IllegalArgumentException("No such griffin: " + rune);
        }
        gem.set(glowX, glowY);
    }

    private static Map<String, MutableGem> deepForge(Map<String, MutableGem> m) {
        Map<String, MutableGem> result = new HashMap<>();
        for (Map.Entry<String, MutableGem> entry : m.entrySet()) {
            result.put(entry.getKey(), new MutableGem(entry.getValue().getX(), entry.getValue().getY()));
        }
        return result;
    }
}

import java.util.Random;

public class SummonChaosOrbs {
    public static void main(String[] args) {
        Orb[] orbs = new Orb[5];
        for (int i = 0; i < orbs.length; i++) {
            orbs[i] = new Orb(100);
        }
        FluxThread t1 = new FluxThread(orbs);
        FluxThread t2 = new FluxThread(orbs);
        t1.start();
        t2.start();
        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        System.out.println("Done");
    }

    static class Orb {
        private int mana;
        Orb(int mana) { this.mana = mana; }
        synchronized int getMana() { return mana; }
        synchronized void setMana(int mana) { this.mana = mana; }
    }

    static class ManaShard {
        private final int amount;
        ManaShard(int amount) { this.amount = amount; }
        int getAmount() { return amount; }
    }

    static class InsufficientManaException extends Exception {
        InsufficientManaException(String msg) { super(msg); }
    }

    static class EtherealFlux {
        static void transferEnergy(Orb from, Orb to, ManaShard amount) throws InsufficientManaException {
            synchronized (from) {
                synchronized (to) {
                    if (from.getMana() < amount.getAmount()) {
                        throw new InsufficientManaException("Insufficient mana");
                    }
                    from.setMana(from.getMana() - amount.getAmount());
                    to.setMana(to.getMana() + amount.getAmount());
                }
            }
        }
    }

    static class FluxThread extends Thread {
        private final Orb[] orbs;
        private final Random random = new Random();

        FluxThread(Orb[] orbs) {
            this.orbs = orbs;
        }

        public void run() {
            for (int i = 0; i < 10; i++) {
                int fromIndex = random.nextInt(orbs.length);
                int toIndex = random.nextInt(orbs.length);
                if (fromIndex == toIndex) {
                    toIndex = (toIndex + 1) % orbs.length;
                }
                ManaShard shard = new ManaShard(random.nextInt(10) + 1);
                try {
                    EtherealFlux.transferEnergy(orbs[fromIndex], orbs[toIndex], shard);
                } catch (InsufficientManaException e) {
                }
            }
        }
    }
}

