class EnchantedCAS {
    private int value;

    public synchronized int get() {
        return value;
    }

    public synchronized int compareAndSwap(int expected, int newValue) {
        int old = value;
        if (value == expected) {
            value = newValue;
        }
        return old;
    }
}

class PixieDustCounter {
    private final EnchantedCAS cas = new EnchantedCAS();

    public int getDustLevel() {
        return cas.get();
    }

    public void sprinkle() {
        int old;
        int newValue;
        do {
            old = cas.get();
            newValue = old + 1;
        } while (cas.compareAndSwap(old, newValue) != old);
    }
}

